import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_score = sum(3 if a == 'C' and b == 'C' else 0 if a == 'C' and b == 'D' else 5 if a == 'D' and b == 'C' else 1 for a, b in history)

    prefix = [0]
    for a, b in history:
        val = 3 if a == 'C' and b == 'C' else 0 if a == 'C' and b == 'D' else 5 if a == 'D' and b == 'C' else 1
        prefix.append(prefix[-1] + val)

    def future_score_for(seq_len, my_first, opp_first):
        total = 0
        for t in range(seq_len):
            if my_first == 'C':
                total += 3 if opp_first == 'C' else 0
            else:
                total += 5 if opp_first == 'C' else 1
        return total

    last_opp = history[-1][1]

    defects = sum(1 for a, b in history if b == 'D')
    recent = history[-12:] if n >= 12 else history
    recent_opp_def = sum(1 for a, b in recent if b == 'D')
    recent_my_def = sum(1 for a, b in recent if a == 'D')

    exploit = False
    if n >= 20:
        tail = history[-20:]
        tail_opp_c = sum(1 for a, b in tail if b == 'C')
        tail_my_c = sum(1 for a, b in tail if a == 'C')
        if tail_opp_c >= 17 and tail_my_c <= 4:
            exploit = True

    mutual_defect_run = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            mutual_defect_run += 1
        else:
            break

    c_run = 0
    for a, b in reversed(history):
        if b == 'C':
            c_run += 1
        else:
            break

    remaining = 100 - n

    if exploit:
        return 'D'

    if mutual_defect_run >= 2:
        if rng.random() < 0.15 and remaining > 3:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if c_run >= 6 and rng.random() < 0.12:
            return 'D'
        return 'C'

    if last_opp == 'D':
        opp_def_rate = defects / n
        if n < 6:
            if rng.random() < 0.7:
                return 'D'
            return 'C'

        if opp_def_rate > 0.6:
            return 'D'

        if recent_opp_def >= 4:
            return 'D'

        if rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'

